// === Tab: mySketch ===
let vertSrc = `
precision highp float;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
}
`;

// Create a string with the fragment shader program.
// The fragment shader is called for each pixel.
let fragSrc = `
precision highp float;
uniform vec2 p;
uniform float r;
const int numIterations = 500;
varying vec2 vTexCoord;

void main() {
  vec2 c = p + gl_FragCoord.xy * r;
  vec2 z = c;
  float n = 0.0;

  for (int i = numIterations; i > 0; i--) {
    if (z.x * z.x + z.y * z.y > 4.0) {
      n = float(i) / float(numIterations);
      break;
    }

    z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;
  }

  gl_FragColor = vec4(
    0.5 - cos(n * 17.0) / 2.0,
    0.5 - cos(n * 13.0) / 2.0,
    0.5 - cos(n * 23.0) / 2.0,
    1.0
  );
}
`;

let mandelbrot;

function setup() {
  createCanvas(100, 100, WEBGL);

  // Create a p5.Shader object.
  mandelbrot = createShader(vertSrc, fragSrc);

  // Apply the p5.Shader object.
  shader(mandelbrot);

  // Set the shader uniform p to an array.
  // p is the center point of the Mandelbrot image.
  mandelbrot.setUniform('p', [-0.74364388703, 0.13182590421]);

  describe('A fractal image zooms in and out of focus.');
}

function draw() {
  // Set the shader uniform r to a value that oscillates
  // between 0 and 0.005.
  // r is the size of the image in Mandelbrot-space.
  let radius = 0.005 * (sin(frameCount * 0.01) + 1);
  mandelbrot.setUniform('r', radius);

  // Style the drawing surface.
  noStroke();

  // Add a plane as a drawing surface.
  plane(100, 100);
}

